// Tap test: the adhkar reader (one surah or dhikr at a time, tap anywhere, undo, audio repeats then moves on,
// options sheet, word by word, word sheet). Run: ENGINE=webkit node adhkar.js out
const pw=require('playwright');const devices=pw.devices;const eng=pw[process.env.ENGINE||'chromium'];const fs=require('fs'),path=require('path');
const ROOT=process.env.ROOT||'/home/user/fastaqim',BASE=process.env.BASE||'/';const MT={'.html':'text/html','.js':'application/javascript','.css':'text/css','.json':'application/json','.png':'image/png','.svg':'image/svg+xml','.woff2':'font/woff2','.woff':'font/woff','.ttf':'font/ttf','.otf':'font/otf','.mp3':'audio/mpeg','.m4a':'audio/mp4','.webmanifest':'application/manifest+json'};
const OUT=process.argv[2]||'qa-adhkar';fs.mkdirSync(OUT,{recursive:true});let fails=0;
const num=t=>t.replace(/\s/g,'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));
const ok=(n,v)=>{console.log((v?'PASS ':'FAIL ')+n);if(!v)fails++};
(async()=>{const b=await eng.launch();const c=await b.newContext({...devices[process.env.DEV||'iPhone 13'],deviceScaleFactor:1});
 await c.route('**/*',r=>{const u0=new URL(r.request().url());if(u0.host!=='fq.test')return r.abort();let u=u0.pathname;if(u.endsWith('/'))u+='index.html';const f=path.join(ROOT,decodeURIComponent(u));
  if(!fs.existsSync(f))return r.fulfill({status:404,body:''});const body=fs.readFileSync(f);const rg=r.request().headers()['range'];
  if(rg){const m=/bytes=(\d*)-(\d*)/.exec(rg);const a=+m[1]||0,e=m[2]?+m[2]:body.length-1;return r.fulfill({status:206,body:body.slice(a,e+1),headers:{'Content-Type':MT[path.extname(f)]||'application/octet-stream','Content-Range':`bytes ${a}-${e}/${body.length}`,'Accept-Ranges':'bytes'}})}
  r.fulfill({body,contentType:MT[path.extname(f)]||'application/octet-stream',headers:{'Accept-Ranges':'bytes'}})});
 if(process.env.STANDALONE)await c.addInitScript(()=>{Object.defineProperty(navigator,'standalone',{get:()=>true});const mm=window.matchMedia.bind(window);window.matchMedia=q=>/standalone/.test(q)?{matches:true,media:q,addListener(){},removeListener(){},addEventListener(){},removeEventListener(){}}:mm(q)});
 const p=await c.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));
 const snap=n=>p.screenshot({path:path.join(OUT,n+'.png')});
 await p.goto('http://fq.test'+BASE+'?nosync=1&z=evening'+(process.env.LANGQ||'').replace('?','&')+'#dhikr');await p.waitForTimeout(1500);
 const ss=await p.evaluate(()=>FQZ.steps(ZS.set).map(s=>s.q?s.keys[0]:s.name));
 ok('Ayat al-Kursi first, then one surah at a time',ss[0]==='2:255'&&ss[1]==='112:1'&&ss[2]==='113:1'&&ss[3]==='114:1');
 ok('repeat default is as many times as needed',await p.evaluate(()=>FQZ.st.rep==='n'));
 await p.evaluate(()=>FQZ.go(1,false));await p.waitForTimeout(300);
 ok('no Unfinished only chip, no list button',!(await p.$('#zOnly'))&&!(await p.$('#zrIx')));
 await snap('1_open');
 const vw=await p.evaluate(()=>[document.documentElement.scrollWidth,innerWidth,document.getElementById('fzD').getBoundingClientRect().bottom,innerHeight]);
 ok('nothing wider than the screen',vw[0]<=vw[1]+1);ok('player fully on screen',vw[2]<=vw[3]+1);
 await p.mouse.click(195,330);await p.waitForTimeout(300);
 ok('tap on the text counts',num(await p.textContent('.fz-num')).startsWith('1/'));
 await p.click('#fzU');await p.waitForTimeout(200);ok('undo takes one off',num(await p.textContent('.fz-num')).startsWith('0/'));
 for(let i=0;i<3;i++){await p.mouse.click(195,300);await p.waitForTimeout(150)}
 await p.waitForTimeout(1200);ok('done after 3 taps and moved on by itself',await p.evaluate(()=>ZS.i===2));
 const tr=await p.evaluate(()=>!!document.querySelector('.fz-tr')&&document.querySelector('.fz-tr').textContent.length>5);ok('transliteration shown for the surah',tr);
 await snap('2_next');
 await p.click('#fzO');await p.waitForTimeout(400);await snap('3_options');
 await p.evaluate(()=>{document.getElementById('sh').scrollTop=400});await p.waitForTimeout(200);
 ok('close button still visible after scrolling the sheet',await p.evaluate(()=>{const x=document.querySelector('#sh [data-x]').getBoundingClientRect(),h=document.getElementById('sh').getBoundingClientRect();return x.top>=h.top-1&&x.bottom<=innerHeight}));await snap('3b_options_scrolled');
 await p.evaluate(()=>{document.getElementById('sh').scrollTop=0});ok('text size slider',await p.isVisible('#fzZ'));
 await p.evaluate(()=>{const z=document.getElementById('fzZ');z.value=150;z.dispatchEvent(new Event('input'))});
 ok('slider makes the text bigger',await p.evaluate(()=>getComputedStyle(document.getElementById('zCard')).getPropertyValue('--fz').trim()==='1.5'));
 ok('no whole-page word mode switch',!(await p.$('#sh [data-k="wbw"]')));
 await p.evaluate(()=>closeSheet());await p.waitForTimeout(300);
 await p.evaluate(()=>FQZ.go(6,false));await p.waitForTimeout(400);
 const wb=await p.evaluate(()=>{const r=document.querySelectorAll('#zCard .fzw')[2].getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2]});
 const c0=num(await p.textContent('.fz-num'));
 await p.mouse.move(wb[0],wb[1]);await p.mouse.down();await p.waitForTimeout(550);await p.mouse.up();await p.waitForTimeout(400);await snap('5_word');
 ok('press and hold a word opens the small word card',await p.evaluate(()=>{const e=document.querySelector('.fz-pop.on');return !!e&&!!e.querySelector('.fz-wa')&&((e.querySelector('.fz-wm')||e.querySelector('.fz-wt')).textContent.length>0)}));
 await p.evaluate(()=>document.querySelector('.fz-pop [data-sl="0"]').click());await p.waitForTimeout(250);
 ok('word plays on its own, cut to the word',await p.evaluate(()=>!!FQZ.WA.src&&FQZ.A.paused));
 ok('word card fully on screen',await p.evaluate(()=>{const r=document.querySelector('.fz-pop').getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0}));
 ok('holding a word does not count',num(await p.textContent('.fz-num'))===c0);
 await p.mouse.click(195,120);await p.waitForTimeout(300);
 ok('tap outside closes the word card without counting',await p.evaluate(()=>!document.querySelector('.fz-pop'))&&num(await p.textContent('.fz-num'))===c0);
 await p.click('#fzTi');await p.waitForTimeout(400);await snap('5b_menu');
 ok('title opens the set menu with 5 sets',await p.evaluate(()=>document.querySelectorAll('#fzM .fz-mr[data-set]').length>=5));
 await p.click('#fzM .fz-mg.open [data-open]');await p.waitForTimeout(150);await p.click('#fzM .fz-mg:nth-child(1) [data-open]');await p.waitForTimeout(400);await snap('5c_menu_list');
 ok('menu lists what is inside a set',await p.evaluate(()=>document.querySelectorAll('#fzM .fz-mg.open .fz-ms').length===11));
 await p.click('#fzM .fz-mr[data-set="morning"]');await p.waitForTimeout(800);
 ok('menu switches to morning',await p.evaluate(()=>ZS.set==='morning'&&FQZ.steps('morning')[0].keys[0]==='2:255'));
 await p.click('#fzTi');await p.waitForTimeout(300);await p.click('#fzM [data-set="evening"]');await p.waitForTimeout(800);
 await p.evaluate(()=>{const z=FQZ.st;z.size=1;z.rate=2;FQZ.go(7,false)});
 await p.click('#fzP');let moved=false,played=false;
 for(let t=0;t<45;t++){await p.waitForTimeout(1000);const r=await p.evaluate(()=>[ZS.i,!FQZ.A.paused]);if(r[1])played=true;if(r[0]===8){moved=true;break}}
 console.log('INFO audio played: '+played);if(played)ok('audio repeated 3 times, then moved to the next dhikr',moved);
 await snap('6_audio');
 await p.evaluate(()=>document.querySelector('[data-go="1"]').click());await p.waitForTimeout(400);
 ok('moving away stops the audio',await p.evaluate(()=>FQZ.A.paused&&!FQZ.AU.on));
 await p.evaluate(()=>{const ss=FQZ.steps('evening');ss.forEach((s,i)=>{if(i!==3){FQZ.go(i,false);const p=S.zk[dkey(NOW())].evening=S.zk[dkey(NOW())].evening||{};p[s.k==null?String(s.j):s.j+'.'+s.k]=s.n;if(s.k==null)p[s.j]=s.n}});FQZ.go(3,false)});
 for(let i=0;i<3;i++){await p.mouse.click(195,300);await p.waitForTimeout(200)}await p.waitForTimeout(2200);await snap('7_celebrate');
 ok('finishing the set celebrates and ticks the Daily checklist',await p.evaluate(()=>!!(S.ci[dkey(NOW())]||{}).evening&&document.getElementById('cel').innerHTML.length>50));
 ok('no page errors',errs.length===0);if(errs.length)console.log(errs.join('\n'));
 await b.close();console.log(fails?'FAILED '+fails:'ALL PASS');process.exit(fails?1:0)})();
